-- Schema 72: Goal/Habit baseline lifecycle and identity-governed personal Habit.
-- The prior schema 71 Registry rows are immutable. This is an explicit BREAKING
-- convergence because Habit now requires an immutable Space Person and read-only
-- lifecycle fields are governed by Actions. Do not infer old owners from creators.
-- If existing Habit records exist, stop instead of silently stranding their history.
-- Backfill the explicitly approved owner relationships before applying schema 72.
CREATE TABLE "_schema72_habit_owner_precondition" (
  "must_be_zero" INTEGER NOT NULL CHECK("must_be_zero"=0)
);
INSERT INTO "_schema72_habit_owner_precondition"("must_be_zero")
SELECT 1 FROM "resource_records" WHERE "model_key"='habit' LIMIT 1;
DROP TABLE "_schema72_habit_owner_precondition";

ALTER TABLE "mdl_goal" ADD COLUMN "status" TEXT NOT NULL DEFAULT 'active'
  CHECK("status" IN ('active','paused','achieved','abandoned'));
CREATE INDEX IF NOT EXISTS "idx_mdl_goal_status" ON "mdl_goal"(space_id,"status",record_id);
ALTER TABLE "mdl_habit" ADD COLUMN "status" TEXT NOT NULL DEFAULT 'active'
  CHECK("status" IN ('active','paused','ended'));
CREATE INDEX IF NOT EXISTS "idx_mdl_habit_status" ON "mdl_habit"(space_id,"status",record_id);

UPDATE model_definitions SET state='superseded',superseded_at=strftime('%Y-%m-%dT%H:%M:%fZ','now')
WHERE model_key IN ('goal','habit') AND state='published';

